use clap::{Args, Parser, Subcommand, ValueEnum};

#[derive(Debug, Parser)]
#[command(name = "kilnctl", version, about = "Plan and inspect kiln firings")]
pub struct Cli {
    #[command(subcommand)]
    pub command: Command,
}

#[derive(Debug, Subcommand)]
pub enum Command {
    /// Print a firing schedule with its ETA
    Plan(PlanArgs),
    /// Show the peak temperature for a cone
    Cone(ConeArgs),
    /// List the whole Orton cone table
    Cones,
    /// Work with firing logs
    Firings(FiringsArgs),
}

#[derive(Debug, Args)]
pub struct PlanArgs {
    #[arg(long, value_enum, default_value_t = PresetArg::FastBisque)]
    pub preset: PresetArg,
    /// Fire to this cone instead of the preset's default peak
    #[arg(long)]
    pub cone: Option<String>,
    /// Start time as HH:MM today (defaults to now)
    #[arg(long)]
    pub start: Option<String>,
    /// Print temperatures in °F
    #[arg(long)]
    pub fahrenheit: bool,
    /// Print the schedule as JSON (for the tablet app)
    #[arg(long)]
    pub json: bool,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum PresetArg {
    FastBisque,
    SlowBisque,
    Glaze6,
    Glaze6SlowCool,
}

#[derive(Debug, Args)]
pub struct ConeArgs {
    /// Cone name, e.g. 6, C6, 04
    pub name: String,
    /// Print °F instead of °C
    #[arg(long)]
    pub fahrenheit: bool,
}

#[derive(Debug, Args)]
pub struct FiringsArgs {
    #[command(subcommand)]
    pub command: FiringsCommand,
}

#[derive(Debug, Subcommand)]
pub enum FiringsCommand {
    /// Read a schedule CSV (as exported by kiln-hub) and print its plan
    Import(ImportArgs),
}

#[derive(Debug, Args)]
pub struct ImportArgs {
    pub path: std::path::PathBuf,
}

